+import * as fs from "fs";
+import * as path from "path";
+
 interface Entry {
   value: string;
   expiresAt: number;
 }

-const store = new Map<string, Entry>();
+const CACHE_DIR = path.join(process.cwd(), ".cache");
+const STORE_FILE = path.join(CACHE_DIR, "store.json");
+
+const ensureCacheDir = (): void => {
+  if (!fs.existsSync(CACHE_DIR)) {
+    fs.mkdirSync(CACHE_DIR, { recursive: true });
+  }
+};
+
+const loadStore = (): Map<string, Entry> => {
+  ensureCacheDir();
+  try {
+    if (fs.existsSync(STORE_FILE)) {
+      const data = fs.readFileSync(STORE_FILE, "utf-8");
+      const entries = JSON.parse(data);
+      return new Map(entries);
+    }
+  } catch {
+    // If file is corrupted, start fresh
+  }
+  return new Map();
+};
+
+const saveStore = (store: Map<string, Entry>): void => {
+  ensureCacheDir();
+  fs.writeFileSync(STORE_FILE, JSON.stringify([...store.entries()]));
+};
+
+let store = loadStore();

 export const put = (key: string, value: string, ttlMs: number): void => {
   store.set(key, { value, expiresAt: Date.now() + ttlMs });
+  saveStore(store);
 };

 export const get = (key: string): string | null => {
@@ -14,6 +46,7 @@ export const get = (key: string): string | null => {
   if (entry === undefined) return null;
   if (entry.expiresAt < Date.now()) {
     store.delete(key);
+    saveStore(store);
     return null;
   }
   return entry.value;
